// The layout of the original executables (SH.EXE, SE.EXE) for the
// synthetic ones (synthetic/le_writer.h): the objects, and at the addresses
// the code reads, the strings (as synthetic text that keeps the original's
// placeholders, line breaks and word lengths; file names kept, being
// identifiers), the pointers between them, the layout numbers and the
// tables generated by rules (synthetic/exe_rules.h).
//
// Extracted by the hidden test "[.synthetic_exe_manifest]" from a trace of
// the addresses the tests read (CMake option SH_TRACE_EXE_READS) into
// tests/synthetic/manifest/{sh,se}_exe.txt, one entry per line:
//
//   object <base> <size> <flags>
//   str <address> "<text>"
//   ptr <address> <target>
//   u8|u16|u32 <address> <value>
//   rule <address> <size> <name>
//
// (numbers in hexadecimal).
#pragma once

#include <cstdint>
#include <filesystem>
#include <set>
#include <string>
#include <string_view>
#include <tuple>
#include <vector>

#include "assets/exe_image.h"

namespace sh::test {

struct ExeManifest {
  struct Object {
    std::uint32_t base = 0;
    std::uint32_t size = 0;
    std::uint32_t flags = 0;
    bool operator==(const Object&) const = default;
  };
  struct String {
    std::uint32_t address = 0;
    std::string text;
    bool operator==(const String&) const = default;
  };
  struct Pointer {
    std::uint32_t address = 0;
    std::uint32_t target = 0;
    bool operator==(const Pointer&) const = default;
  };
  struct Value {
    std::uint32_t address = 0;
    std::uint8_t size = 4;
    std::uint32_t value = 0;
    bool operator==(const Value&) const = default;
  };
  struct Rule {
    std::uint32_t address = 0;
    std::uint32_t size = 0;
    std::string name;
    bool operator==(const Rule&) const = default;
  };

  std::vector<Object> objects;
  std::vector<String> strings;
  std::vector<Pointer> pointers;
  std::vector<Value> values;
  std::vector<Rule> rules;

  bool operator==(const ExeManifest&) const = default;
};

// One traced read: address, size and kind (assets/exe_image.h).
using TracedRead = std::tuple<std::uint32_t, std::size_t, sh::ExeRead>;

// Returns the reads of the image ending at `image_end` in the trace file
// `path` (game_exe_setup.cpp's format).
std::set<TracedRead> read_exe_trace(const std::filesystem::path& path, std::uint32_t image_end);

#ifdef SH_TRACE_EXE_READS
// Returns the manifest of `image` for the traced `reads`; `rules` are the
// ranges whose values are generated (exe_rules.h).
ExeManifest extract_exe_manifest(const ExeImage& image, const std::set<TracedRead>& reads,
                                 const std::vector<ExeManifest::Rule>& rules);
#endif

// Returns `text` with its letters replaced by synthetic ones (word lengths,
// case, digits, punctuation, placeholders and control characters kept), or
// unchanged when it is a file name or another identifier.
std::string synthetic_text(std::string_view text, std::uint32_t seed);

std::string format_exe_manifest(const ExeManifest& manifest);
ExeManifest parse_exe_manifest(std::string_view text);

// Returns the committed manifest `name` ("sh_exe" or "se_exe").
const ExeManifest& committed_exe_manifest(std::string_view name);
std::filesystem::path exe_manifest_path(std::string_view name);

}  // namespace sh::test
